"use client"

import * as React from "react"
import {
  EASINGS,
  GlimmProvider,
  useGlimm,
  type EasingName,
  type GlimmDefaults,
  type PaletteName,
} from "glimm/react"

const DISPLAYED_EASINGS = [
  "snap",
  "linear",
  "ease",
  "easeOutQuart",
  "easeInCubic",
  "easeInOutCubic",
  "easeOutExpo",
  "back",
] satisfies ReadonlyArray<EasingName>

type GlimmEasingProps = Omit<GlimmDefaults, "easing" | "palette"> & {
  className?: string
  initialEasing?: EasingName
  palette?: PaletteName
}

function EyeIcon() {
  return (
    <svg
      aria-hidden="true"
      fill="none"
      height="13"
      viewBox="0 0 24 24"
      width="13"
    >
      <path
        clipRule="evenodd"
        d="M12.0015 4C15.8807 4.00003 19.6594 6.31907 22.1829 10.7475C22.6254 11.524 22.6254 12.476 22.1829 13.2526C19.6594 17.681 15.8806 20 12.0015 19.9999C8.12239 19.9999 4.34363 17.6809 1.82016 13.2524C1.37766 12.4759 1.37766 11.5239 1.82016 10.7474C4.34363 6.31896 8.1224 3.99997 12.0015 4ZM8.3765 12C8.3765 9.99797 9.99947 8.375 12.0015 8.375C14.0036 8.375 15.6265 9.99797 15.6265 12C15.6265 14.002 14.0036 15.625 12.0015 15.625C9.99947 15.625 8.3765 14.002 8.3765 12Z"
        fill="currentColor"
        fillRule="evenodd"
      />
    </svg>
  )
}

function EasingPanel({
  initialEasing,
  palette,
}: {
  initialEasing: EasingName
  palette: PaletteName
}) {
  const [selected, setSelected] = React.useState<EasingName>(initialEasing)
  const { sweep } = useGlimm()

  const points = React.useMemo(() => {
    const easing = EASINGS[selected]

    return Array.from({ length: 61 }, (_, index) => {
      const progress = index / 60
      const x = 2 + progress * 96
      const y = 96 - easing(progress) * 92
      return `${x.toFixed(1)},${y.toFixed(1)}`
    }).join(" ")
  }, [selected])

  const preview = React.useCallback(
    () => sweep(() => undefined, { easing: selected, palette }),
    [palette, selected, sweep],
  )

  return (
    <>
      <div
        style={{
          background: "#f7f7f7",
          borderRadius: "12px",
          boxShadow: "inset 0 0 0 0.5px rgba(0,0,0,0.04)",
          padding: "13px",
        }}
      >
        <div
          style={{
            backgroundImage:
              "radial-gradient(circle, rgba(0,0,0,0.08) 1px, transparent 1px)",
            backgroundPosition: "0 0",
            backgroundSize: "12px 12px",
            borderRadius: "8px",
            padding: "13px",
          }}
        >
          <svg
            aria-label={`${selected} easing curve`}
            preserveAspectRatio="none"
            role="img"
            viewBox="0 0 100 100"
            style={{ display: "block", height: "184px", margin: "0 auto", width: "72%" }}
          >
            <polyline
              fill="none"
              points={points}
              stroke="#242529"
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeWidth="1.5"
              vectorEffect="non-scaling-stroke"
            />
          </svg>
        </div>

        <div
          style={{
            display: "flex",
            flexWrap: "nowrap",
            gap: "5px",
            marginTop: "13px",
            minWidth: 0,
            overflowX: "auto",
          }}
        >
          {DISPLAYED_EASINGS.map((name) => {
            const active = name === selected

            return (
              <button
                key={name}
                aria-pressed={active}
                onClick={() => setSelected(name)}
                type="button"
                style={{
                  background: active ? "#242529" : "rgba(0,0,0,0.04)",
                  border: "none",
                  borderRadius: "999px",
                  color: active ? "#ffffff" : "#9ca3af",
                  cursor: "pointer",
                  flexShrink: 0,
                  fontFamily: "Inter, ui-sans-serif, system-ui, sans-serif",
                  fontSize: "13px",
                  fontWeight: 450,
                  height: "26px",
                  letterSpacing: "-0.18px",
                  lineHeight: "18px",
                  padding: "0 10px",
                }}
              >
                {name}
              </button>
            )
          })}
        </div>
      </div>

      <div
        style={{
          alignItems: "center",
          display: "flex",
          gap: "8px",
          justifyContent: "flex-end",
          marginTop: "13px",
        }}
      >
        <button
          aria-label="Preview"
          onClick={preview}
          type="button"
          style={{
            alignItems: "center",
            background: "#242529",
            border: "none",
            borderRadius: "999px",
            boxShadow:
              "0 0 0 0.75px #27272a inset, 0 0 0 1.25px rgba(255,255,255,0.30) inset, 0 8px 16px rgba(0,0,0,0.08), 0 16px 32px rgba(0,0,0,0.08)",
            color: "#ffffff",
            cursor: "pointer",
            display: "inline-flex",
            flexShrink: 0,
            fontFamily: "Inter, ui-sans-serif, system-ui, sans-serif",
            fontSize: "12px",
            fontWeight: 450,
            gap: "6px",
            height: "28px",
            letterSpacing: "-0.1px",
            lineHeight: "18px",
            padding: "0 12px 0 10px",
            transition:
              "background-color 160ms cubic-bezier(0.23, 1, 0.32, 1), color 160ms cubic-bezier(0.23, 1, 0.32, 1), transform 160ms cubic-bezier(0.23, 1, 0.32, 1)",
          }}
        >
          <EyeIcon />
          Preview
        </button>
      </div>
    </>
  )
}

function GlimmEasing({
  className,
  initialEasing = "snap",
  palette = "spectrum",
  ...defaults
}: GlimmEasingProps) {
  return (
    <GlimmProvider {...defaults}>
      <main
        className={className}
        style={{
          alignItems: "center",
          background: "#ffffff",
          color: "#242529",
          display: "flex",
          justifyContent: "center",
          minHeight: "100vh",
          padding: "48px 32px",
          width: "100%",
        }}
      >
        <section style={{ maxWidth: "634px", width: "100%" }}>
          <EasingPanel initialEasing={initialEasing} palette={palette} />
        </section>
      </main>
    </GlimmProvider>
  )
}

export { DISPLAYED_EASINGS, GlimmEasing }
export default GlimmEasing

